mapper.select:
select  from nad_program


        and (name like concat('%', #{q}, '%')
             or name_cn like concat('%', #{q}, '%')
             or field like concat('%', #{q}, '%'))

    and university_id = #{universityId}
    and program_type = #{type}
    and teaching_language = #{language}
    and field = #{field}
    and is_featured = #{featured}
    and is_hot = #{hot}
    and is_recommended = #{recommended}
    and status = #{status}
    and publish_status = #{publishStatus}

order by is_featured desc, is_recommended desc, is_hot desc, name asc, id asc

select id, program_id, term, application_open, application_close, sort_order
from nad_program_intake where program_id = #{programId}
order by sort_order asc, id asc
